/// Returns the class of `cp`, which must be at most U+10FFFF.
pub fn classOf(cp: u21) Class {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (ranges[mid].last < cp) lo = mid + 1 else hi = mid;
    }
    return ranges[lo].class;
}
